// Busca el inmueble (exacto o por contencion) y arma el registro base
const referencia = ($json.body?.inmueble || '').trim();
const filas = $input.all().map(i => i.json);
const norm = (t) => String(t ?? '').toLowerCase().normalize('NFKD').replace(/\p{Diacritic}/gu, '');
const ref = norm(referencia);
const fila = filas.find(f =>
  Object.values(f).some(v => norm(v) === ref)
) || filas.find(f =>
  Object.values(f).some(v => { const nv = norm(v); return nv && (nv.includes(ref) || ref.includes(nv)); })
) || {};
return [{ json: { inmueble: fila, email_inquilino: $json.body?.email_inquilino || '', process_id: crypto.randomUUID?.() || $execution.id } }];

// Prefila del arrendador con la ultima fila del mismo inmueble y derivados calculados
const fila = $json.inmueble || {};
const dir = Object.values(fila).find(v => /col\./i.test(String(v))) || '';
const contratos = $('Leer DatosRenda').all().map(i => i.json)
  .filter(c => String(c['Inmueble en arrendamiento'] || '').toLowerCase().includes(String(fila['Inmuebles en arrendamiento'] || dir).toLowerCase()));
const arrendador = contratos[contratos.length - 1] || {};

const dec = (t) => { const n = parseFloat(String(t ?? '').replace(/[^0-9.]/g, '')); return isNaN(n) ? null : n; };
const letras = (n) => new Intl.NumberFormat('es-MX', { style: 'currency', currency: 'MXN' }).format(n);
const renta = dec(arrendador['Renta mensual bruta']);
const dcto = dec(arrendador['Descuento PP']) || 0;
const fecha = arrendador['Fecha Firma'] ? new Date(arrendador['Fecha Firma']) : null;
const fleg = fecha ? fecha.toLocaleDateString('es-MX', { day: 'numeric', month: 'long', year: 'numeric' }) : '';

const derivados = renta === null ? {} : {
  'Texto renta mensual bruta': letras(renta),
  'Valor del periodo': letras(renta * 12),
  'Descuento PP': letras(dcto),
  'Total con dcto pp': letras(renta - dcto)
};
if (fecha && !isNaN(fecha)) {
  derivados['Fecha Firma'] = fleg;
  derivados['D\u00eda de pago mensual'] = String(fecha.getDate());
  derivados['A\u00f1o firma texto'] = String(fecha.getFullYear());
}
return [{ json: { arrendador, derivados, proceso: { inmueble: fila, email_inquilino: $json.email_inquilino, process_id: $json.process_id } } }];

// Yo (n8n) no(extrae con LLM: sustituye por un nodo OpenAI / Mistral / Gemini.
// Entrada: correos del inquilino. Salida: [{campo, valor, evidencia}] contra el catalogo de campos.
const correos = $input.all().map(i => i.json);
return [{ json: { documentos: correos.map(c => ({ de: c.from, asunto: c.subject, fecha: c.date, adjuntos: (c.attachments || []).length })) , extraido: [] } }];

// Llenado de {{tokens}} sobre document.xml (zip in-memory; n8n Code no trae papa zip nativa:
// usa el nodo Google Docs 'create document from template' o tu propia librería de zip con addons).
// Aquí solo demuestra el contrato de datos.
const { arrendador, derivados, proceso } = $input.item.json;
const valores = { ...arrendador, ...derivados, ...{} };
return [{ json: { valores, titulo: `${proceso.inmueble['Arrendatario nuevo'] || proceso.email_inquilino} - Arrendamiento`, carpeta_id: '187lKT8g582TR20MLvGtG0jodpIcBg3kp' } }];
